// square millimeter converter — area (jahdb demo program)
// Exact factors to square meter. Factors per NIST definitions.
var TABLE=[["square millimeter","mm2",1e-06], ["square centimeter","cm2",0.0001], ["square meter","m2",1.0], ["are","a",100.0], ["hectare","ha",10000.0], ["square kilometer","km2",1000000.0], ["square inch","in2",0.00064516], ["square foot","ft2",0.09290304], ["square yard","yd2",0.83612736], ["square chain","ch2",404.6856], ["square link","li2",0.0404686], ["rood","rood",1011.714], ["perch","perch",25.2929], ["acre","ac",4046.8564224], ["section","section",2589988.110336], ["township","twp",93239571.97], ["square mile","mi2",2589988.110336], ["barn","b",1e-28], ["circular mil","cmil",5.067075e-10], ["dunam","dunam",1000.0], ["ping","ping",3.30579], ["football field","field",5351.0], ["soccer field","pitch",7140.0], ["tennis court","court",260.9], ["olympic pool","pool",1250.0]];
function toBase(v,name){name=String(name).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===name||TABLE[i][1].toLowerCase()===name)return v*TABLE[i][2];}throw new Error("unknown unit: "+name);}
function convert(v,from,to){var b=toBase(v,from);to=String(to).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===to||TABLE[i][1].toLowerCase()===to)return b/TABLE[i][2];}throw new Error("unknown unit: "+to);}
// demo: 1 square millimeter expressed in every unit of this database
console.log(TABLE.map(function(u){return "1 square millimeter = "+convert(1,"square millimeter",u[0])+" "+u[0]+" ("+u[1]+")";}).join("\n"));

